import { d as db } from "../../../../../chunks/db.js";
import { g as getEmpresaId } from "../../../../../chunks/get-empresa-id.js";
import { s as serialize } from "../../../../../chunks/utils3.js";
const load = async ({ request }) => {
  const empresaId = await getEmpresaId(request);
  const produtos = await db.produto.findMany({
    where: { empresaId },
    include: {
      categoria: {
        select: { nome: true }
      },
      fornecedor: {
        select: { nome: true }
      },
      taxa: {
        select: { valor: true, descricao: true }
      }
    },
    orderBy: {
      createdAt: "desc"
    }
  });
  return serialize({
    produtos
  });
};
const actions = {};
export {
  actions,
  load
};
